-- 0014: общая переаттестация проще и понятнее. Новый пул из 54 вопросов простыми словами (один верный ответ,
-- категории «Общая переаттестация — …», источник content/reatt-full/questions.json). Общая переаттестация (28 вопросов, 60 минут) берёт вопросы
-- только из этого пула. Прежние вопросы остаются в банке (резерв) и используются упрощённой переаттестацией, «Кейсами» и экзаменами.
-- Идемпотентно: вопросы вставляются только если такого ext_id ещё нет; переключение — только если состав блоков не меняли вручную.
UPDATE reattestations SET groups = '[{"label":"ПК","categories":["Общая переаттестация — ПК"],"questions":4,"cases":0,"pref_types":["single"],"pref_count":4},{"label":"УК","categories":["Общая переаттестация — УК"],"questions":3,"cases":0,"pref_types":["single"],"pref_count":3},{"label":"ВУ","categories":["Общая переаттестация — ВУ"],"questions":6,"cases":0,"pref_types":["single"],"pref_count":6},{"label":"СУ","categories":["Общая переаттестация — СУ"],"questions":2,"cases":0,"pref_types":["single"],"pref_count":2},{"label":"КПС","categories":["Общая переаттестация — КПС"],"questions":2,"cases":0,"pref_types":["single"],"pref_count":2},{"label":"ДУ","categories":["Общая переаттестация — ДУ"],"questions":2,"cases":0,"pref_types":["single"],"pref_count":2},{"label":"ФЗ / ФКЗ / КоАП","categories":["Общая переаттестация — Законы"],"questions":6,"cases":0,"pref_types":["single"],"pref_count":6},{"label":"ТК","categories":["Общая переаттестация — ТК"],"questions":3,"cases":0,"pref_types":["single"],"pref_count":3}]',
  description = '28 простых вопросов с одним верным ответом: процессуальный и уголовный кодексы, уставы, законы, ТК. Проверяется автоматически, результат сразу после отправки.',
  updated_at = CAST(strftime('%s','now') AS INTEGER) * 1000
